{"command":"cd /tmp/subs && python - <<'PY'
import zipfile, ast

def npy_header(b):
    assert b[:6] == b'\x93NUMPY', b[:6]
    major, minor = b[6], b[7]
    if major == 1:
        hl = int.from_bytes(b[8:10], 'little'); off = 10
    else:
        hl = int.from_bytes(b[8:12], 'little'); off = 12
    return ast.literal_eval(b[off:off+hl].decode('latin1').strip().rstrip('\x00').strip()), off+hl

for n in range(1, 11):
    fn = f'model_{n:02d}.npz'
    try:
        z = zipfile.ZipFile(fn)
    except Exception as e:
        print(fn, 'ERR', e); continue
    print(f'--- {fn}')
    for name in z.namelist():
        b = z.read(name)
        h, data_off = npy_header(b)
        print(f'    {name:20s} dtype={h["descr"]!s:8s} shape={str(h["shape"]):10s} fortran={h["fortran_order"]} raw={b[data_off:data_off+80]!r}')
PY"}
